-- =====================================================================
-- AlumNect - Dữ liệu mẫu Mentoring (demo)
-- File: seed_mentoring_demo.sql
-- Tạo: 14 mentor (ACTIVE, có gói đăng ký, hồ sơ, kinh nghiệm), 8 sinh viên,
--      24 yêu cầu ở mọi trạng thái, deal / thanh toán / task / nhật ký / đánh giá,
--      1 nhóm mentoring. Dữ liệu cũ KHÔNG bị xóa; có thể chạy lại (tự bỏ qua nếu đã có).
-- Tài khoản demo: email mentor.01@seed.alumnect.vn ... mentor.14@seed.alumnect.vn, student.01@seed.alumnect.vn ... student.08@seed.alumnect.vn
--                 Mật khẩu chung: Alumnect@123
-- Gỡ dữ liệu: chạy seed_mentoring_demo_cleanup.sql
-- Chạy: psql -U <user> -d <db> -v ON_ERROR_STOP=1 -f seed_mentoring_demo.sql
-- =====================================================================
BEGIN;
SET LOCAL client_min_messages = notice;

DO $guard$
BEGIN
    IF EXISTS (SELECT 1 FROM users WHERE email = 'mentor.01@seed.alumnect.vn') THEN
        RAISE EXCEPTION 'Dữ liệu mẫu mentoring đã tồn tại. Chạy seed_mentoring_demo_cleanup.sql trước nếu muốn tạo lại.';
    END IF;
END
$guard$;

