FROM (VALUES
    ('mentor.01@seed.alumnect.vn', 'Nguyễn Hoàng Long', 'https://randomuser.me/api/portraits/men/32.jpg', 'https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=1200&q=60', '0930000137', 1, 12, 'SE129101', 'Senior Backend Engineer tại VNG Corporation', 'Hơn 8 năm làm backend cho các hệ thống hàng triệu người dùng. Mình đã dẫn dắt nhiều bạn sinh viên FPTU từ viết CRUD đầu tiên đến offer thực tập tại các công ty công nghệ lớn.', 'FPTU TP.HCM', 2016, 'TP. Hồ Chí Minh'),
    ('mentor.02@seed.alumnect.vn', 'Trần Thị Minh Anh', 'https://randomuser.me/api/portraits/women/44.jpg', 'https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=1200&q=60', '0930000274', 4, 13, 'SE139102', 'Product Manager tại MoMo', 'Từng là lập trình viên rồi chuyển sang quản lý sản phẩm fintech. Mình có thể giúp bạn xây portfolio sản phẩm, luyện case phỏng vấn PM và hiểu một ngày làm việc thật của PM.', 'FPTU TP.HCM', 2017, 'TP. Hồ Chí Minh'),
    ('mentor.03@seed.alumnect.vn', 'Lê Quang Huy', 'https://randomuser.me/api/portraits/men/45.jpg', 'https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=1200&q=60', '0930000411', 1, 14, 'SE149103', 'DevOps & Cloud Engineer tại Viettel Solutions', 'Chuyên xây dựng pipeline và hạ tầng cloud. Mình thích kèm các nhóm đồ án đưa sản phẩm lên cloud thật, có giám sát và quy trình triển khai rõ ràng.', 'FPTU Hà Nội', 2018, 'Hà Nội'),
    ('mentor.04@seed.alumnect.vn', 'Phạm Thu Hà', 'https://randomuser.me/api/portraits/women/68.jpg', 'https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=1200&q=60', '0930000548', 7, 13, 'SE139104', 'UX/UI Design Lead tại Tiki', 'Nhiều năm dẫn dắt đội thiết kế sản phẩm thương mại điện tử. Mình review portfolio rất kỹ và luôn chỉ ra cách kể câu chuyện thiết kế thuyết phục nhà tuyển dụng.', 'FPTU TP.HCM', 2017, 'TP. Hồ Chí Minh'),
    ('mentor.05@seed.alumnect.vn', 'Đặng Văn Khoa', 'https://randomuser.me/api/portraits/men/22.jpg', 'https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=1200&q=60', '0930000685', 3, 14, 'SE149105', 'Data Scientist tại VinAI', 'Làm việc trong nhóm nghiên cứu AI ứng dụng. Mình đồng hành cùng các bạn muốn bước vào Data/AI, từ xây nền toán đến làm đồ án có dữ liệu thật.', 'FPTU Hà Nội', 2018, 'Hà Nội'),
    ('mentor.06@seed.alumnect.vn', 'Vũ Ngọc Lan', 'https://randomuser.me/api/portraits/women/26.jpg', 'https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=1200&q=60', '0930000822', 9, 12, 'SE129106', 'Marketing Manager tại Unilever Vietnam', 'Quản lý chiến dịch FMCG quy mô quốc gia. Mình giúp các nhóm đồ án marketing đi từ insight khách hàng đến kế hoạch triển khai và đo lường thực tế.', 'FPTU TP.HCM', 2016, 'TP. Hồ Chí Minh'),
    ('mentor.07@seed.alumnect.vn', 'Bùi Anh Tuấn', 'https://randomuser.me/api/portraits/men/54.jpg', 'https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=1200&q=60', '0930000959', 1, 13, 'SE139107', 'Mobile Engineer (React Native) tại Grab', 'Phát triển ứng dụng mobile cho hàng triệu tài xế và hành khách. Mình hướng dẫn từ chọn kiến trúc, quản lý trạng thái đến phát hành và theo dõi lỗi.', 'FPTU TP.HCM', 2017, 'TP. Hồ Chí Minh'),
    ('mentor.08@seed.alumnect.vn', 'Hoàng Thị Mai', 'https://randomuser.me/api/portraits/women/12.jpg', 'https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=1200&q=60', '0930001096', 4, 11, 'SE119108', 'Chuyên viên Tài chính doanh nghiệp tại Techcombank', 'Làm việc trong khối tài chính doanh nghiệp, am hiểu lộ trình ngân hàng và đầu tư. Mình hỗ trợ sinh viên chọn hướng đi và chuẩn bị vòng tuyển dụng ngân hàng.', 'FPTU Hà Nội', 2015, 'Hà Nội'),
    ('mentor.09@seed.alumnect.vn', 'Ngô Minh Đức', 'https://randomuser.me/api/portraits/men/75.jpg', 'https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=1200&q=60', '0930001233', 2, 14, 'SE149109', 'Security Engineer tại FPT Software', 'Làm pentest và đánh giá bảo mật cho khách hàng quốc tế. Mình hướng dẫn xây nền tảng ATTT bài bản và cách tham gia CTF để tạo hồ sơ nổi bật.', 'FPTU Đà Nẵng', 2018, 'Đà Nẵng'),
    ('mentor.10@seed.alumnect.vn', 'Đỗ Khánh Linh', 'https://randomuser.me/api/portraits/women/65.jpg', 'https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=1200&q=60', '0930001370', 11, 12, 'SE129110', 'Talent Acquisition Lead tại Samsung Vietnam', 'Hàng nghìn CV đã đi qua tay mình mỗi năm. Mình chỉ ra chính xác nhà tuyển dụng nhìn gì trong 30 giây đầu và giúp bạn kể câu chuyện nghề nghiệp rõ ràng.', 'FPTU Đà Nẵng', 2016, 'Bắc Ninh'),
    ('mentor.11@seed.alumnect.vn', 'Phan Thanh Sơn', 'https://randomuser.me/api/portraits/men/18.jpg', 'https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=1200&q=60', '0930001507', 5, 11, 'SE119111', 'Founder & Tech Lead tại startup EdTech', 'Đã xây và vận hành sản phẩm EdTech từ con số 0. Mình đồng hành cùng các nhóm muốn biến đồ án thành sản phẩm thật, từ MVP đến những khách hàng đầu tiên.', 'FPTU TP.HCM', 2015, 'TP. Hồ Chí Minh'),
    ('mentor.12@seed.alumnect.vn', 'Võ Thị Bảo Châu', 'https://randomuser.me/api/portraits/women/33.jpg', 'https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=1200&q=60', '0930001644', 9, 13, 'SE139112', 'Content & PR Manager tại Vingroup', 'Phụ trách truyền thông cho các dự án lớn của tập đoàn. Mình giúp sinh viên truyền thông xây portfolio nội dung và tự tin làm việc với báo chí, đối tác.', 'FPTU Hà Nội', 2017, 'Hà Nội'),
    ('mentor.13@seed.alumnect.vn', 'Lý Gia Bảo', 'https://randomuser.me/api/portraits/men/9.jpg', 'https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=1200&q=60', '0930001781', 4, 14, 'SE149113', 'Business Analyst tại NashTech', 'Làm BA cho các dự án outsourcing quốc tế. Mình hướng dẫn cách làm việc với khách hàng nước ngoài, viết yêu cầu rõ ràng và luyện phỏng vấn BA bằng tiếng Anh.', 'FPTU TP.HCM', 2018, 'TP. Hồ Chí Minh'),
