    ('mentor.06@seed.alumnect.vn', 'Quản lý chiến dịch FMCG quy mô quốc gia. Mình giúp các nhóm đồ án marketing đi từ insight khách hàng đến kế hoạch triển khai và đo lường thực tế.', 'BOTH', 'BOTH', 4.80, 13, 760),
    ('mentor.07@seed.alumnect.vn', 'Phát triển ứng dụng mobile cho hàng triệu tài xế và hành khách. Mình hướng dẫn từ chọn kiến trúc, quản lý trạng thái đến phát hành và theo dõi lỗi.', 'ONLINE', 'BOTH', 4.90, 12, 820),
    ('mentor.08@seed.alumnect.vn', 'Làm việc trong khối tài chính doanh nghiệp, am hiểu lộ trình ngân hàng và đầu tư. Mình hỗ trợ sinh viên chọn hướng đi và chuẩn bị vòng tuyển dụng ngân hàng.', 'BOTH', 'INDIVIDUAL', 4.70, 8, 520),
    ('mentor.09@seed.alumnect.vn', 'Làm pentest và đánh giá bảo mật cho khách hàng quốc tế. Mình hướng dẫn xây nền tảng ATTT bài bản và cách tham gia CTF để tạo hồ sơ nổi bật.', 'ONLINE', 'BOTH', 4.60, 7, 480),
    ('mentor.10@seed.alumnect.vn', 'Hàng nghìn CV đã đi qua tay mình mỗi năm. Mình chỉ ra chính xác nhà tuyển dụng nhìn gì trong 30 giây đầu và giúp bạn kể câu chuyện nghề nghiệp rõ ràng.', 'BOTH', 'BOTH', 4.90, 21, 990),
    ('mentor.11@seed.alumnect.vn', 'Đã xây và vận hành sản phẩm EdTech từ con số 0. Mình đồng hành cùng các nhóm muốn biến đồ án thành sản phẩm thật, từ MVP đến những khách hàng đầu tiên.', 'BOTH', 'BOTH', 4.80, 10, 690),
    ('mentor.12@seed.alumnect.vn', 'Phụ trách truyền thông cho các dự án lớn của tập đoàn. Mình giúp sinh viên truyền thông xây portfolio nội dung và tự tin làm việc với báo chí, đối tác.', 'ONLINE', 'BOTH', 4.50, 6, 410),
    ('mentor.13@seed.alumnect.vn', 'Làm BA cho các dự án outsourcing quốc tế. Mình hướng dẫn cách làm việc với khách hàng nước ngoài, viết yêu cầu rõ ràng và luyện phỏng vấn BA bằng tiếng Anh.', 'ONLINE', 'BOTH', 4.70, 9, 530),
    ('mentor.14@seed.alumnect.vn', 'Hơn 7 năm giảng dạy tiếng Anh cho sinh viên và người đi làm. Mình giúp bạn tự tin phỏng vấn, thuyết trình và giao tiếp chuyên nghiệp bằng tiếng Anh.', 'ONLINE', 'BOTH', 4.80, 15, 700)
) AS m(email, bio, working_mode, mentoring_type, rating, review_count, rep)
JOIN users u ON u.email = m.email;

