INSERT INTO mentoring_requests (student_id, industry_id, title, description, budget_min, budget_max, working_mode, participation_type, task_type, expected_deadline, status, matched_count, created_at, updated_at, target_mentor_id, request_type, group_id, client_request_key)
VALUES ((SELECT id FROM users WHERE email = 'student.01@seed.alumnect.vn'), 1, 'Định hướng lộ trình Backend Java cho kỳ thực tập', 'Em là sinh viên năm ba, đã học Java Core và Spring Boot cơ bản. Em cần mentor đánh giá năng lực hiện tại, tư vấn lộ trình học Microservices và chuẩn bị cho kỳ thực tập Backend trong 6 tháng tới.', 300000, 600000, 'ONLINE', 'INDIVIDUAL', 'CAREER_ORIENTATION', now() - interval '58 days' - interval '0 hours' + interval '21 days', 'MATCHED', 1, now() - interval '58 days' - interval '0 hours', now(), NULL, 'GENERAL', NULL, 'seed-r01');
INSERT INTO mentoring_requests (student_id, industry_id, title, description, budget_min, budget_max, working_mode, participation_type, task_type, expected_deadline, status, matched_count, created_at, updated_at, target_mentor_id, request_type, group_id, client_request_key)
VALUES ((SELECT id FROM users WHERE email = 'student.02@seed.alumnect.vn'), 4, 'Review portfolio UX/UI cho vị trí Product Designer Intern', 'Em đã có 3 case study trên Behance nhưng chưa biết kể câu chuyện thiết kế thế nào cho thuyết phục. Em cần mentor góp ý cấu trúc case study, cách trình bày quy trình và chọn dự án nổi bật.', 200000, 500000, 'ONLINE', 'INDIVIDUAL', 'RESUME_REVIEW', now() - interval '44 days' - interval '0 hours' + interval '21 days', 'MATCHED', 1, now() - interval '44 days' - interval '0 hours', now(), (SELECT mp.id FROM mentor_profiles mp JOIN users u ON u.id = mp.user_id WHERE u.email = 'mentor.04@seed.alumnect.vn'), 'DIRECT', NULL, 'seed-r02');
INSERT INTO mentoring_requests (student_id, industry_id, title, description, budget_min, budget_max, working_mode, participation_type, task_type, expected_deadline, status, matched_count, created_at, updated_at, target_mentor_id, request_type, group_id, client_request_key)
VALUES ((SELECT id FROM users WHERE email = 'student.05@seed.alumnect.vn'), 1, 'Xây dựng mô hình dự đoán cho đồ án tốt nghiệp', 'Nhóm em làm đồ án dự đoán nhu cầu sử dụng điện nhưng mô hình overfit. Em cần mentor xem lại cách chia dữ liệu, chọn đặc trưng và đánh giá mô hình.', 400000, 800000, 'ONLINE', 'INDIVIDUAL', 'CAPSTONE_ADVICE', now() - interval '40 days' - interval '0 hours' + interval '21 days', 'MATCHED', 1, now() - interval '40 days' - interval '0 hours', now(), NULL, 'GENERAL', NULL, 'seed-r03');
INSERT INTO mentoring_requests (student_id, industry_id, title, description, budget_min, budget_max, working_mode, participation_type, task_type, expected_deadline, status, matched_count, created_at, updated_at, target_mentor_id, request_type, group_id, client_request_key)
VALUES ((SELECT id FROM users WHERE email = 'student.06@seed.alumnect.vn'), 5, 'Xây dựng thương hiệu cá nhân cho sinh viên truyền thông', 'Em muốn xây kênh LinkedIn và blog cá nhân để ứng tuyển thực tập PR. Em cần mentor giúp định vị bản thân, lên lịch nội dung và cách viết bài thu hút nhà tuyển dụng.', 200000, 400000, 'ONLINE', 'INDIVIDUAL', 'CAREER_ORIENTATION', now() - interval '33 days' - interval '0 hours' + interval '21 days', 'MATCHED', 1, now() - interval '33 days' - interval '0 hours', now(), NULL, 'GENERAL', NULL, 'seed-r04');
INSERT INTO mentoring_requests (student_id, industry_id, title, description, budget_min, budget_max, working_mode, participation_type, task_type, expected_deadline, status, matched_count, created_at, updated_at, target_mentor_id, request_type, group_id, client_request_key)
VALUES ((SELECT id FROM users WHERE email = 'student.04@seed.alumnect.vn'), 8, 'Review CV và luyện phỏng vấn hành vi cho vị trí Business Intern', 'Em sắp ứng tuyển thực tập tại các tập đoàn lớn. Em cần mentor review CV một trang và luyện trả lời các câu hỏi phỏng vấn hành vi theo phương pháp STAR.', 250000, 500000, 'ONLINE', 'INDIVIDUAL', 'RESUME_REVIEW', now() - interval '27 days' - interval '0 hours' + interval '21 days', 'MATCHED', 1, now() - interval '27 days' - interval '0 hours', now(), (SELECT mp.id FROM mentor_profiles mp JOIN users u ON u.id = mp.user_id WHERE u.email = 'mentor.10@seed.alumnect.vn'), 'DIRECT', NULL, 'seed-r05');
INSERT INTO mentoring_requests (student_id, industry_id, title, description, budget_min, budget_max, working_mode, participation_type, task_type, expected_deadline, status, matched_count, created_at, updated_at, target_mentor_id, request_type, group_id, client_request_key)
VALUES ((SELECT id FROM users WHERE email = 'student.08@seed.alumnect.vn'), 6, 'Luyện phỏng vấn tiếng Anh cho vị trí Business Analyst', 'Em cần luyện cách giới thiệu bản thân, trình bày kinh nghiệm dự án và trả lời câu hỏi tình huống bằng tiếng Anh. Mong mentor sửa cách dùng từ, phát âm và giúp em chuẩn bị bộ câu trả lời ngắn gọn.', 300000, 600000, 'ONLINE', 'INDIVIDUAL', 'MOCK_INTERVIEW', now() - interval '21 days' - interval '0 hours' + interval '21 days', 'MATCHED', 1, now() - interval '21 days' - interval '0 hours', now(), NULL, 'GENERAL', NULL, 'seed-r06');
INSERT INTO mentoring_requests (student_id, industry_id, title, description, budget_min, budget_max, working_mode, participation_type, task_type, expected_deadline, status, matched_count, created_at, updated_at, target_mentor_id, request_type, group_id, client_request_key)
VALUES ((SELECT id FROM users WHERE email = 'student.07@seed.alumnect.vn'), 8, 'Chuyển hướng từ QA sang Business Analyst', 'Em có một năm làm QA thủ công và muốn chuyển sang Business Analyst. Em cần mentor đánh giá kiến thức hiện tại, đề xuất lộ trình ba tháng và góp ý hồ sơ cá nhân.', 300000, 600000, 'ONLINE', 'INDIVIDUAL', 'CAREER_ORIENTATION', now() - interval '18 days' - interval '0 hours' + interval '21 days', 'MATCHED', 1, now() - interval '18 days' - interval '0 hours', now(), NULL, 'GENERAL', NULL, 'seed-r07');
INSERT INTO mentoring_requests (student_id, industry_id, title, description, budget_min, budget_max, working_mode, participation_type, task_type, expected_deadline, status, matched_count, created_at, updated_at, target_mentor_id, request_type, group_id, client_request_key)
VALUES ((SELECT id FROM users WHERE email = 'student.01@seed.alumnect.vn'), 1, 'Hoàn thiện ứng dụng React Native cho đồ án và phát hành thử', 'Nhóm em xây dựng ứng dụng quản lý sự kiện bằng React Native/Expo. Em cần mentor hỗ trợ cấu trúc dự án, quản lý trạng thái và quy trình phát hành bản thử nghiệm.', 500000, 1000000, 'ONLINE', 'INDIVIDUAL', 'TECHNICAL_CONSULTING', now() - interval '12 days' - interval '0 hours' + interval '21 days', 'MATCHED', 1, now() - interval '12 days' - interval '0 hours', now(), NULL, 'GENERAL', NULL, 'seed-r08');
INSERT INTO mentoring_requests (student_id, industry_id, title, description, budget_min, budget_max, working_mode, participation_type, task_type, expected_deadline, status, matched_count, created_at, updated_at, target_mentor_id, request_type, group_id, client_request_key)
VALUES ((SELECT id FROM users WHERE email = 'student.02@seed.alumnect.vn'), 4, 'Xây dựng Design System cho dự án nhóm', 'Nhóm em có 12 màn hình nhưng màu sắc và nút bấm chưa nhất quán. Em cần mentor hướng dẫn xây Design System gọn trong Figma và quy ước đặt tên component.', 400000, 800000, 'ONLINE', 'INDIVIDUAL', 'TECHNICAL_CONSULTING', now() - interval '9 days' - interval '0 hours' + interval '21 days', 'MATCHED', 1, now() - interval '9 days' - interval '0 hours', now(), (SELECT mp.id FROM mentor_profiles mp JOIN users u ON u.id = mp.user_id WHERE u.email = 'mentor.04@seed.alumnect.vn'), 'DIRECT', NULL, 'seed-r09');
INSERT INTO mentoring_requests (student_id, industry_id, title, description, budget_min, budget_max, working_mode, participation_type, task_type, expected_deadline, status, matched_count, created_at, updated_at, target_mentor_id, request_type, group_id, client_request_key)
VALUES ((SELECT id FROM users WHERE email = 'student.03@seed.alumnect.vn'), 1, 'Lộ trình ATTT và chuẩn bị tham gia CTF', 'Em muốn theo ngành an toàn thông tin nhưng chưa biết bắt đầu từ đâu. Em cần lộ trình học, tài nguyên luyện CTF và cách xây hồ sơ cá nhân cho vị trí thực tập pentest.', 250000, 500000, 'ONLINE', 'INDIVIDUAL', 'CAREER_ORIENTATION', now() - interval '7 days' - interval '0 hours' + interval '21 days', 'MATCHED', 1, now() - interval '7 days' - interval '0 hours', now(), NULL, 'GENERAL', NULL, 'seed-r10');
INSERT INTO mentoring_requests (student_id, industry_id, title, description, budget_min, budget_max, working_mode, participation_type, task_type, expected_deadline, status, matched_count, created_at, updated_at, target_mentor_id, request_type, group_id, client_request_key)
VALUES ((SELECT id FROM users WHERE email = 'student.05@seed.alumnect.vn'), 1, 'Đưa đồ án Spring Boot lên cloud với CI/CD', 'Em đang hoàn thiện API cho đồ án và gặp khó khăn khi đóng gói Docker, cấu hình PostgreSQL và triển khai lên cloud. Em cần một buổi tư vấn để rà soát kiến trúc, xử lý lỗi triển khai và xây dựng checklist vận hành.', 500000, 900000, 'ONLINE', 'INDIVIDUAL', 'TECHNICAL_CONSULTING', now() - interval '15 days' - interval '0 hours' + interval '21 days', 'MATCHED', 1, now() - interval '15 days' - interval '0 hours', now(), (SELECT mp.id FROM mentor_profiles mp JOIN users u ON u.id = mp.user_id WHERE u.email = 'mentor.03@seed.alumnect.vn'), 'DIRECT', NULL, 'seed-r11');
INSERT INTO mentoring_requests (student_id, industry_id, title, description, budget_min, budget_max, working_mode, participation_type, task_type, expected_deadline, status, matched_count, created_at, updated_at, target_mentor_id, request_type, group_id, client_request_key)
VALUES ((SELECT id FROM users WHERE email = 'student.06@seed.alumnect.vn'), 3, 'Tư vấn kế hoạch marketing cho thương hiệu cà phê địa phương', 'Nhóm đang xây dựng kế hoạch marketing số cho một thương hiệu cà phê địa phương. Cần mentor góp ý chân dung khách hàng, thông điệp chiến dịch, lựa chọn kênh và bộ KPI đo lường.', 400000, 800000, 'ONLINE', 'INDIVIDUAL', 'CAPSTONE_ADVICE', now() - interval '2 days' - interval '0 hours' + interval '21 days', 'MATCHED', 1, now() - interval '2 days' - interval '0 hours', now(), NULL, 'GENERAL', NULL, 'seed-r12');
INSERT INTO mentoring_requests (student_id, industry_id, title, description, budget_min, budget_max, working_mode, participation_type, task_type, expected_deadline, status, matched_count, created_at, updated_at, target_mentor_id, request_type, group_id, client_request_key)
VALUES ((SELECT id FROM users WHERE email = 'student.07@seed.alumnect.vn'), 1, 'Chuẩn bị phỏng vấn Product Manager Associate', 'Em muốn ứng tuyển vị trí Associate PM sau khi tốt nghiệp. Em cần mentor luyện phỏng vấn case sản phẩm, đo lường và ưu tiên tính năng.', 300000, 700000, 'ONLINE', 'INDIVIDUAL', 'MOCK_INTERVIEW', now() - interval '3 days' - interval '0 hours' + interval '21 days', 'OPEN', 1, now() - interval '3 days' - interval '0 hours', now(), NULL, 'GENERAL', NULL, 'seed-r13');
INSERT INTO mentoring_requests (student_id, industry_id, title, description, budget_min, budget_max, working_mode, participation_type, task_type, expected_deadline, status, matched_count, created_at, updated_at, target_mentor_id, request_type, group_id, client_request_key)
VALUES ((SELECT id FROM users WHERE email = 'student.04@seed.alumnect.vn'), 2, 'Tư vấn lộ trình vào ngành Ngân hàng - Tài chính', 'Em học Quản trị kinh doanh và muốn vào ngân hàng. Em cần mentor định hướng chứng chỉ, kỹ năng Excel và cách chuẩn bị các vòng tuyển dụng ngân hàng.', 200000, 450000, 'BOTH', 'INDIVIDUAL', 'CAREER_ORIENTATION', now() - interval '4 days' - interval '0 hours' + interval '21 days', 'OPEN', 1, now() - interval '4 days' - interval '0 hours', now(), NULL, 'GENERAL', NULL, 'seed-r14');
INSERT INTO mentoring_requests (student_id, industry_id, title, description, budget_min, budget_max, working_mode, participation_type, task_type, expected_deadline, status, matched_count, created_at, updated_at, target_mentor_id, request_type, group_id, client_request_key)
VALUES ((SELECT id FROM users WHERE email = 'student.02@seed.alumnect.vn'), 4, 'Góp ý đồ án thiết kế ứng dụng đặt đồ ăn trong khuôn viên trường', 'Nhóm cần phản biện kế hoạch trải nghiệm người dùng cho ứng dụng đặt đồ ăn trong khuôn viên trường. Phạm vi gồm khảo sát người dùng, luồng đặt hàng và kiểm thử khả dụng.', 300000, 700000, 'ONLINE', 'INDIVIDUAL', 'CAPSTONE_ADVICE', now() - interval '1 days' - interval '0 hours' + interval '21 days', 'OPEN', 3, now() - interval '1 days' - interval '0 hours', now(), NULL, 'GENERAL', NULL, 'seed-r15');
INSERT INTO mentoring_requests (student_id, industry_id, title, description, budget_min, budget_max, working_mode, participation_type, task_type, expected_deadline, status, matched_count, created_at, updated_at, target_mentor_id, request_type, group_id, client_request_key)
VALUES ((SELECT id FROM users WHERE email = 'student.03@seed.alumnect.vn'), 1, 'Cần mentor review mã nguồn bảo mật cho ứng dụng web đồ án', 'Em làm ứng dụng web quản lý đồ án và muốn có người rà soát các lỗ hổng phổ biến như SQL injection, XSS và phân quyền. Mong mentor chỉ ra điểm yếu và hướng sửa.', 400000, 900000, 'ONLINE', 'INDIVIDUAL', 'TECHNICAL_CONSULTING', now() - interval '2 days' - interval '0 hours' + interval '21 days', 'OPEN', 3, now() - interval '2 days' - interval '0 hours', now(), NULL, 'GENERAL', NULL, 'seed-r16');
INSERT INTO mentoring_requests (student_id, industry_id, title, description, budget_min, budget_max, working_mode, participation_type, task_type, expected_deadline, status, matched_count, created_at, updated_at, target_mentor_id, request_type, group_id, client_request_key)
VALUES ((SELECT id FROM users WHERE email = 'student.08@seed.alumnect.vn'), 6, 'Luyện thuyết trình tiếng Anh cho buổi bảo vệ đồ án', 'Em cần luyện thuyết trình đồ án bằng tiếng Anh trong 10 phút, gồm phát âm, nhịp độ và cách trả lời câu hỏi phản biện.', 250000, 500000, 'ONLINE', 'INDIVIDUAL', 'MOCK_INTERVIEW', now() - interval '1 days' - interval '0 hours' + interval '21 days', 'OPEN', 2, now() - interval '1 days' - interval '0 hours', now(), NULL, 'GENERAL', NULL, 'seed-r17');
