VALUES ((SELECT id FROM users WHERE email = 'student.05@seed.alumnect.vn'), 1, 'Định hướng nghiên cứu sau đại học ngành AI', 'Em muốn tìm hiểu cách chuẩn bị hồ sơ học bổng và liên hệ giảng viên hướng dẫn ở nước ngoài cho ngành AI.', 300000, 600000, 'ONLINE', 'INDIVIDUAL', 'CAREER_ORIENTATION', now() - interval '5 days' - interval '0 hours' + interval '21 days', 'OPEN', 2, now() - interval '5 days' - interval '0 hours', now(), NULL, 'GENERAL', NULL, 'seed-r18');
INSERT INTO mentoring_requests (student_id, industry_id, title, description, budget_min, budget_max, working_mode, participation_type, task_type, expected_deadline, status, matched_count, created_at, updated_at, target_mentor_id, request_type, group_id, client_request_key)
VALUES ((SELECT id FROM users WHERE email = 'student.01@seed.alumnect.vn'), 1, 'Review kiến trúc Microservices cho đồ án quản lý sự kiện', 'Em gửi trực tiếp tới anh Long: nhóm em tách hệ thống thành 4 service nhưng còn nhiều chỗ chưa hợp lý về giao tiếp và dữ liệu. Em mong được anh review kiến trúc.', 500000, 1000000, 'ONLINE', 'INDIVIDUAL', 'TECHNICAL_CONSULTING', now() - interval '1 days' - interval '0 hours' + interval '21 days', 'OPEN', 1, now() - interval '1 days' - interval '0 hours', now(), (SELECT mp.id FROM mentor_profiles mp JOIN users u ON u.id = mp.user_id WHERE u.email = 'mentor.01@seed.alumnect.vn'), 'DIRECT', NULL, 'seed-r19');
