VALUES ((SELECT id FROM users WHERE email = 'student.06@seed.alumnect.vn'), 5, 'Xây dựng portfolio nội dung truyền thông', 'Em muốn nhờ chị Châu góp ý cách chọn bài viết, thiết kế portfolio và cách trình bày chiến dịch đã tham gia khi ứng tuyển thực tập truyền thông.', 200000, 400000, 'ONLINE', 'INDIVIDUAL', 'RESUME_REVIEW', now() - interval '2 days' - interval '0 hours' + interval '21 days', 'OPEN', 1, now() - interval '2 days' - interval '0 hours', now(), (SELECT mp.id FROM mentor_profiles mp JOIN users u ON u.id = mp.user_id WHERE u.email = 'mentor.12@seed.alumnect.vn'), 'DIRECT', NULL, 'seed-r20');
