VALUES ((SELECT id FROM users WHERE email = 'student.07@seed.alumnect.vn'), 8, 'Cần mentor hướng dẫn khởi nghiệp cho dự án thương mại điện tử', 'Em có ý tưởng sàn thương mại điện tử đồ cũ trong sinh viên và muốn kiểm chứng thị trường trước khi làm sản phẩm.', 300000, 600000, 'ONLINE', 'INDIVIDUAL', 'CAREER_ORIENTATION', now() - interval '25 days' - interval '0 hours' + interval '21 days', 'CANCELLED', 1, now() - interval '25 days' - interval '0 hours', now(), NULL, 'GENERAL', NULL, 'seed-r21');
