VALUES ((SELECT id FROM users WHERE email = 'student.04@seed.alumnect.vn'), 3, 'Review plan marketing cho CLB sinh viên', 'Em phụ trách truyền thông cho CLB và cần người xem lại kế hoạch tuyển thành viên mới.', 150000, 300000, 'ONLINE', 'INDIVIDUAL', 'CAPSTONE_ADVICE', now() - interval '40 days' - interval '0 hours' + interval '21 days', 'EXPIRED', 1, now() - interval '40 days' - interval '0 hours', now(), NULL, 'GENERAL', NULL, 'seed-r22');
