VALUES ((SELECT id FROM users WHERE email = 'student.01@seed.alumnect.vn'), 1, 'Cần người xem lại CV cho kỳ thực tập mùa hè', 'Em đã được mentor khác hỗ trợ và không cần tiếp tục yêu cầu này nữa.', 150000, 300000, 'ONLINE', 'INDIVIDUAL', 'RESUME_REVIEW', now() - interval '30 days' - interval '0 hours' + interval '21 days', 'CLOSED', 1, now() - interval '30 days' - interval '0 hours', now(), NULL, 'GENERAL', NULL, 'seed-r23');
