VALUES ((SELECT id FROM users WHERE email = 'student.05@seed.alumnect.vn'), 1, 'Xây dựng lộ trình Cloud & DevOps 12 tuần cho nhóm', 'Nhóm bốn sinh viên CNTT muốn có lộ trình 12 tuần về Linux, Docker, CI/CD và nền tảng cloud. Cần mentor xác định thứ tự kiến thức, bài tập thực hành và một dự án chung để đưa vào portfolio.', 1200000, 2500000, 'ONLINE', 'GROUP', 'TECHNICAL_CONSULTING', now() - interval '11 days' - interval '0 hours' + interval '21 days', 'MATCHED', 1, now() - interval '11 days' - interval '0 hours', now(), NULL, 'GENERAL', (SELECT id FROM mentoring_groups WHERE name = 'Nhóm Cloud & DevOps K19'), 'seed-r24');
