INSERT INTO mentor_reviews (mentor_profile_id, student_id, rating, comment, points_awarded, created_at, updated_at, task_id)
SELECT (SELECT mp.id FROM mentor_profiles mp JOIN users u ON u.id = mp.user_id WHERE u.email = 'mentor.13@seed.alumnect.vn'), t.student_id, 4, 'Anh Bảo cho em lộ trình ba tháng rõ ràng và mẫu tài liệu yêu cầu để em thực hành. Em đã bắt đầu viết user story cho dự án nhỏ.', 6, t.completed_at + interval '1 day', now(), t.id FROM mentoring_tasks t WHERE t.id = (SELECT id FROM mentoring_tasks WHERE request_id = (SELECT id FROM mentoring_requests WHERE client_request_key = 'seed-r07'));

-- 14. Đồng bộ số task hoàn thành của mentor
UPDATE mentor_profiles mp SET completed_tasks = (SELECT COUNT(*) FROM mentoring_tasks t WHERE t.mentor_id = mp.user_id AND t.status = 'COMPLETED')
WHERE mp.user_id IN (SELECT id FROM users WHERE email LIKE 'mentor.%@seed.alumnect.vn');

